import{_ as t,o,c as r,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Epic: Connector Store & SDK","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/epics/connector-store-sdk.md","filePath":"sovereign-edge/epics/connector-store-sdk.md"}'),a={name:"sovereign-edge/epics/connector-store-sdk.md"};function s(i,e,c,l,p,d){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-connector-store-sdk" tabindex="-1">Epic: Connector Store &amp; SDK <a class="header-anchor" href="#epic-connector-store-sdk" aria-label="Permalink to &quot;Epic: Connector Store &amp; SDK&quot;">​</a></h1><blockquote><p>Phase 3 — opening the connector layer to third-party developers: SDK, plugin template, examples, public registry, and the in-app store.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>📋 Planned</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Mirrors <code>sovereign</code>&#39;s own plugin-development trio (<code>sovereign-plugin-template</code></p><ul><li><code>sovereign-plugins-examples</code> + the public plugin registry), adapted for connectors instead of Next.js modules. This is deliberately the <strong>last</strong> phase — everything here builds on the <a href="./connector-framework.html">Connector Framework</a> unchanged, per research 0001&#39;s &quot;build once, widen without rework&quot; principle.</li></ul><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-5-1-—-connector-sdk" tabindex="-1">📋 5.1 — Connector SDK <a class="header-anchor" href="#📋-5-1-—-connector-sdk" aria-label="Permalink to &quot;📋 5.1 — Connector SDK&quot;">​</a></h4><p><strong>Goal:</strong> A published package with the manifest schema types and a validator, for connector authors to build and test against before submission.</p><p><strong>Deliverables:</strong></p><ul><li>Zero-dependency package (mirrors <code>@sovereignfs/sdk</code>&#39;s own zero-dep constraint) exporting the Tier 1/Tier 2 manifest types and a validator function.</li><li>Versioned independently, with the same &quot;no breaking changes in a patch&quot; discipline <code>sovereign</code>&#39;s SDK follows once this is a public contract.</li></ul><p><strong>Dependencies:</strong> Connector Framework epic (2.1) — reuses its schema directly, does not redefine it.</p><p><strong>Review checklist:</strong></p><ul><li>The SDK&#39;s validator accepts the exact same manifests the app&#39;s own runtime (epic 2.4) already accepts — no drift between author-time and load-time validation.</li></ul><hr><h4 id="📋-5-2-—-connector-plugin-template" tabindex="-1">📋 5.2 — Connector plugin template <a class="header-anchor" href="#📋-5-2-—-connector-plugin-template" aria-label="Permalink to &quot;📋 5.2 — Connector plugin template&quot;">​</a></h4><p><strong>Goal:</strong> A &quot;use this template&quot; starting point for a new third-party connector.</p><p><strong>Deliverables:</strong></p><ul><li>Template repo: example manifest, README explaining the tiers and submission process, optional Tier 2 script skeleton.</li></ul><p><strong>Dependencies:</strong> Task 5.1.</p><p><strong>Review checklist:</strong></p><ul><li>A developer unfamiliar with the project can go from cloning the template to a submittable connector manifest without reading source code.</li></ul><hr><h4 id="📋-5-3-—-first-party-example-connectors" tabindex="-1">📋 5.3 — First-party example connectors <a class="header-anchor" href="#📋-5-3-—-first-party-example-connectors" aria-label="Permalink to &quot;📋 5.3 — First-party example connectors&quot;">​</a></h4><p><strong>Goal:</strong> A reference set demonstrating the range of what a connector can be, mirroring <code>sovereign-plugins-examples</code>.</p><p><strong>Deliverables:</strong></p><ul><li>A simple Tier 1 REST connector, one with token auth, one Tier 2 connector with a transform script, one demonstrating the paid/entitlement flow (epic 6).</li></ul><p><strong>Dependencies:</strong> Task 5.1, Task 6 (monetization, for the paid example).</p><p><strong>Review checklist:</strong></p><ul><li>Each example validates against the SDK and installs/runs in the app unmodified.</li></ul><hr><h4 id="📋-5-4-—-public-connector-registry-and-submission-process" tabindex="-1">📋 5.4 — Public connector registry and submission process <a class="header-anchor" href="#📋-5-4-—-public-connector-registry-and-submission-process" aria-label="Permalink to &quot;📋 5.4 — Public connector registry and submission process&quot;">​</a></h4><p><strong>Goal:</strong> A reviewable, public index of connectors third parties can submit to.</p><p><strong>Deliverables:</strong></p><ul><li>A JSON index (mirrors <code>sovereign</code>&#39;s <code>registry/plugins.json</code> pattern) plus a submission process (PR-based or a form).</li><li>Review checklist for submissions: declared network domain matches what the manifest actually calls, pricing is declared honestly, tool schema is sane. Lighter review burden than native-code review, since Tier 1/2 connectors ship no arbitrary executable code.</li></ul><p><strong>Dependencies:</strong> Task 5.1.</p><p><strong>Review checklist:</strong></p><ul><li>A submitted connector manifest that lies about its declared network domain is caught by the review process before publication.</li></ul><hr><h4 id="📋-5-5-—-in-app-connector-store" tabindex="-1">📋 5.5 — In-app Connector Store <a class="header-anchor" href="#📋-5-5-—-in-app-connector-store" aria-label="Permalink to &quot;📋 5.5 — In-app Connector Store&quot;">​</a></h4><p><strong>Goal:</strong> The end-user-facing browse/install surface.</p><p><strong>Deliverables:</strong></p><ul><li>Browse, search, install, and manage connectors from the registry, inside the app.</li><li>Per-connector permission grant happens at install time, reusing epic 2.2&#39;s consent model unchanged.</li></ul><p><strong>Dependencies:</strong> Task 5.4, Connector Framework epic (2.2).</p><p><strong>Review checklist:</strong></p><ul><li>Installing a third-party connector from the store goes through the exact same permission-grant flow as the first-party Search/Sovereign Tasks connectors — no separate, weaker path for third-party connectors.</li></ul><hr><h4 id="📋-5-6-—-tier-2-sandboxed-script-runtime" tabindex="-1">📋 5.6 — Tier 2 sandboxed script runtime <a class="header-anchor" href="#📋-5-6-—-tier-2-sandboxed-script-runtime" aria-label="Permalink to &quot;📋 5.6 — Tier 2 sandboxed script runtime&quot;">​</a></h4><p><strong>Goal:</strong> Implement the sandboxed execution environment Tier 2 connectors run in.</p><p><strong>Deliverables:</strong></p><ul><li>A capability-restricted script engine (candidates: an embedded Hermes isolate, QuickJS, or WASM — choice deferred to a spike, see research 0001&#39;s open questions) with no ambient filesystem/network/device access beyond what the host explicitly injects as call parameters.</li></ul><p><strong>Dependencies:</strong> Task 5.1; blocked on a real Tier 2 use case existing (per research 0001, don&#39;t build this speculatively before something needs it).</p><p><strong>Review checklist:</strong></p><ul><li>A Tier 2 script cannot access anything — network, filesystem, other connectors&#39; credentials — beyond what was explicitly injected as its input parameters.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./connector-framework.html">Connector Framework</a></li><li><code>confluence/concepts/plugin-development.md</code> (the <code>sovereign</code> pattern this mirrors, in the workbench repo)</li></ul>',57)])])}const m=t(a,[["render",s]]);export{u as __pageData,m as default};
